//! 万法归一的统一媒体提取树
use std::collections::HashMap;
use serde::{Deserialize, Serialize};
struct ScannedMedia { has_video: bool, has_audio: bool, has_images: bool, video_sources: Vec<String>, audio_sources: Vec<String>, image_urls: Vec<String>, first_video_poster: Option<String>, subtitles: Vec<SubtitleEntry> }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum MediaType { Video, Audio, Image, Article, SocialPost, Playlist, Channel, LiveStream, Unknown }
impl MediaType { pub fn name(&self) -> &'static str { match self { MediaType::Video => "video", MediaType::Audio => "audio", MediaType::Image => "image", MediaType::Article => "article", MediaType::SocialPost => "social_post", MediaType::Playlist => "playlist", MediaType::Channel => "channel", MediaType::LiveStream => "live_stream", MediaType::Unknown => "unknown", } } }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct VideoInfo { pub video_id: String, pub title: String, pub description: String, pub duration_secs: Option<f64>, pub upload_date: Option<String>, pub uploader: Option<String>, pub uploader_id: Option<String>, pub channel_id: Option<String>, pub thumbnail_url: Option<String>, pub tags: Vec<String>, pub view_count: Option<u64>, pub like_count: Option<u64>, pub comment_count: Option<u64>, pub subtitles: Vec<SubtitleEntry>, pub formats: Vec<FormatEntry> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SubtitleEntry { pub language: String, pub language_code: String, pub is_auto_generated: bool, pub url: Option<String>, pub content: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FormatEntry { pub format_id: String, pub ext: String, pub width: Option<u32>, pub height: Option<u32>, pub tbr: Option<f64>, pub filesize: Option<u64>, pub url: Option<String>, pub protocol: String, pub vcodec: Option<String>, pub acodec: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AudioInfo { pub title: String, pub artist: Option<String>, pub album: Option<String>, pub duration_secs: Option<f64>, pub uploader: Option<String>, pub thumbnail_url: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ImageInfo { pub url: String, pub title: Option<String>, pub width: Option<u32>, pub height: Option<u32>, pub alt_text: Option<String>, pub source: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ArticleInfo { pub title: String, pub author: Option<String>, pub publish_date: Option<String>, pub content_text: String, pub content_html: Option<String>, pub excerpt: Option<String>, pub images: Vec<ImageInfo>, pub source_url: String, pub site_name: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SocialInfo { pub platform: String, pub post_id: String, pub author: String, pub content: String, pub media_urls: Vec<String>, pub like_count: Option<u64>, pub repost_count: Option<u64>, pub reply_count: Option<u64>, pub timestamp: Option<String> }
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExtractedMedia { pub source_url: String, pub media_type: MediaType, pub title: String, pub description: String, pub extractor: String, pub raw_metadata: HashMap<String, String>, pub video: Option<VideoInfo>, pub audio: Option<AudioInfo>, pub image: Option<ImageInfo>, pub article: Option<ArticleInfo>, pub social: Option<SocialInfo> }
impl ExtractedMedia { pub fn new(url: &str, mt: MediaType, title: &str) -> Self { Self { source_url: url.into(), media_type: mt, title: title.into(), description: String::new(), extractor: "extraction_tree".into(), raw_metadata: HashMap::new(), video: None, audio: None, image: None, article: None, social: None } } pub fn text_content(&self) -> String { let mut p = vec![self.title.clone()]; if !self.description.is_empty() { p.push(self.description.clone()); } if let Some(ref v) = self.video { p.push(v.description.clone()); for s in &v.subtitles { if let Some(ref c) = s.content { p.push(c.clone()); } } } if let Some(ref a) = self.article { p.push(a.content_text.clone()); } if let Some(ref s) = self.social { p.push(s.content.clone()); } p.join("

") } }
#[derive(Debug)]
pub enum ExtractResult { Media(ExtractedMedia), MediaList(Vec<ExtractedMedia>), Unsupported(String), Error(String) }
pub struct ExtractionTree;
impl ExtractionTree { pub fn extract(url: &str) -> ExtractResult { let html = match Self::fetch(url) { Ok(h) => h, Err(e) => return ExtractResult::Error(format!("Fetch: {e}")) }; let meta = Self::parse_meta(&html); let ld = Self::parse_json_ld(&html); let me = Self::scan_media(&html); let tx = Self::extract_text(&html); let title = meta.get("og:title").or_else(|| meta.get("twitter:title")).or_else(|| meta.get("title")).cloned().or_else(|| Self::extract_title(&html)).unwrap_or_else(|| url.to_string()); let desc = meta.get("og:description").or_else(|| meta.get("twitter:description")).or_else(|| meta.get("description")).cloned().unwrap_or_default(); let pt = if me.has_video { MediaType::Video } else if me.has_audio { MediaType::Audio } else if me.has_images { MediaType::Image } else { MediaType::Article }; let mut mc = ExtractedMedia::new(url, pt, &title); mc.description = desc; mc.raw_metadata = meta.clone(); if me.has_video { mc.video = Some(VideoInfo { video_id: Self::video_id(url), title: title.clone(), description: tx.clone(), duration_secs: ld.get("duration").and_then(|s| s.parse().ok()), upload_date: ld.get("datePublished").cloned().or_else(|| meta.get("article:published_time").cloned()), uploader: ld.get("author.name").cloned().or_else(|| meta.get("og:video:actor").cloned()), uploader_id: None, channel_id: None, thumbnail_url: meta.get("og:image").cloned().or_else(|| me.first_video_poster.clone()), tags: Vec::new(), view_count: None, like_count: None, comment_count: None, subtitles: me.subtitles, formats: Vec::new() }); } else if let Some(vs) = me.video_sources.first() { mc.video = Some(VideoInfo { video_id: Self::video_id(url), title: title.clone(), description: tx.clone(), duration_secs: None, upload_date: None, uploader: None, uploader_id: None, channel_id: None, thumbnail_url: me.first_video_poster.clone(), tags: Vec::new(), view_count: None, like_count: None, comment_count: None, subtitles: me.subtitles, formats: vec![FormatEntry { format_id: "default".into(), ext: vs.as_str().split('.').last().unwrap_or("mp4").split('?').next().unwrap_or("mp4").to_string(), width: None, height: None, tbr: None, filesize: None, url: Some(vs.clone()), protocol: "https".into(), vcodec: None, acodec: None }] }); } if let Some(_) = me.audio_sources.first() { mc.audio = Some(AudioInfo { title: title.clone(), artist: ld.get("author.name").cloned().or_else(|| meta.get("music:musician").cloned()), album: meta.get("music:album").cloned(), duration_secs: ld.get("duration").and_then(|s| s.parse().ok()).or_else(|| meta.get("music:duration").and_then(|s| s.parse().ok())), uploader: ld.get("author.name").cloned(), thumbnail_url: meta.get("og:image").cloned() }); } let oi = meta.get("og:image").cloned(); let mut imgs: Vec<ImageInfo> = Vec::new(); for iu in &me.image_urls { imgs.push(ImageInfo { url: iu.clone(), title: meta.get("og:image:alt").cloned().or_else(|| Some(title.clone())), width: meta.get("og:image:width").and_then(|w| w.parse().ok()), height: meta.get("og:image:height").and_then(|h| h.parse().ok()), alt_text: meta.get("og:image:alt").cloned(), source: meta.get("og:site_name").cloned() }); } if let Some(ref oi) = oi { if !imgs.iter().any(|i| i.url == *oi) { imgs.push(ImageInfo { url: oi.clone(), title: Some(title.clone()), width: meta.get("og:image:width").and_then(|w| w.parse().ok()), height: meta.get("og:image:height").and_then(|h| h.parse().ok()), alt_text: meta.get("og:image:alt").cloned(), source: meta.get("og:site_name").cloned() }); } } if let Some(f) = imgs.into_iter().next() { mc.image = Some(f); } let ct = if tx.len() > 20 { tx } else { String::new() }; mc.article = Some(ArticleInfo { title, author: ld.get("author.name").cloned().or_else(|| meta.get("og:article:author").cloned()), publish_date: ld.get("datePublished").cloned().or_else(|| meta.get("article:published_time").cloned()), content_text: ct, content_html: None, excerpt: meta.get("og:description").cloned(), images: Vec::new(), source_url: url.to_string(), site_name: meta.get("og:site_name").cloned() }); ExtractResult::Media(mc) }
fn fetch(url: &str) -> Result<String, String> { let c = reqwest::blocking::Client::builder().user_agent("Mozilla/5.0").timeout(std::time::Duration::from_secs(30)).build().map_err(|e| format!("Client: {e}"))?; c.get(url).header("Accept-Language", "zh-CN,zh;q=0.9,en;q=0.8").send().map_err(|e| format!("HTTP: {e}"))?.text().map_err(|e| format!("Read: {e}")) }
fn parse_meta(html: &str) -> HashMap<String, String> { let mut m = HashMap::new(); for c in html.split("<meta").skip(1) { let t = c.split('>').next().unwrap_or(""); let n = Self::attr(t, "property").or_else(|| Self::attr(t, "name")); if let Some(n) = n { if let Some(v) = Self::attr(t, "content") { m.insert(n, v); } } } if !m.contains_key("title") && !m.contains_key("og:title") { if let Some(t) = Self::extract_title(html) { m.insert("title".into(), t); } } m }
fn extract_title(html: &str) -> Option<String> { let s = html.find("<title")?; let a = html[s..].find('>')?; let c = &html[s + a + 1..]; let e = c.find("</title>")?; Some(c[..e].trim().to_string()) }
fn attr(f: &str, n: &str) -> Option<String> { let p = format!("{n}=""); let s = f.find(&p)?; let vs = s + p.len(); let ve = f[vs..].find('"')?; Some(f[vs..vs + ve].to_string()) }
fn parse_json_ld(html: &str) -> HashMap<String, String> { let mut m = HashMap::new(); for p in html.split(r#"<script type="application/ld+json">"#).skip(1) { if let Ok(v) = serde_json::from_str::<serde_json::Value>(p.split("</script>").next().unwrap_or("")) { Self::flatten(&v, String::new(), &mut m); } } m }
fn flatten(v: &serde_json::Value, p: String, o: &mut HashMap<String, String>) { match v { serde_json::Value::Object(m) => { for (k, v) in m { let k = if p.is_empty() { k.clone() } else { format!("{p}.{k}") }; Self::flatten(v, k, o); } } serde_json::Value::String(s) => { o.insert(p, s.clone()); } serde_json::Value::Number(n) => { o.insert(p, n.to_string()); } serde_json::Value::Array(a) => { if let Some(f) = a.first() { Self::flatten(f, p, o); } } _ => {} } }
fn scan_media(html: &str) -> ScannedMedia { let mut sm = ScannedMedia { has_video: false, has_audio: false, has_images: false, video_sources: Vec::new(), audio_sources: Vec::new(), image_urls: Vec::new(), first_video_poster: None, subtitles: Vec::new() }; for c in html.split("<video").skip(1) { sm.has_video = true; let t = c.split('>').next().unwrap_or(""); if let Some(p) = Self::attr(t, "poster") { if sm.first_video_poster.is_none() { sm.first_video_poster = Some(url_resolve(&p)); } } let inner = c.split('>').skip(1).collect::<Vec<_>>().join(">"); let bf = inner.split("</video>").next().unwrap_or(&inner); for s in bf.split("<source").skip(1) { if let Some(s) = Self::attr(s, "src") { sm.video_sources.push(url_resolve(&s)); } } for tr in inner.split("<track").skip(1) { let k = Self::attr(tr, "kind").unwrap_or_default(); if k == "subtitles" || k == "captions" { if let Some(src) = Self::attr(tr, "src") { let l = Self::attr(tr, "srclang").unwrap_or_else(|| "unknown".into()); let lb = Self::attr(tr, "label").unwrap_or_else(|| l.clone()); sm.subtitles.push(SubtitleEntry { language: lb, language_code: l, is_auto_generated: false, url: Some(url_resolve(&src)), content: None }); } } } if let Some(s) = Self::attr(t, "src") { sm.video_sources.push(url_resolve(&s)); } } for c in html.split("<audio").skip(1) { sm.has_audio = true; let t = c.split('>').next().unwrap_or(""); if let Some(s) = Self::attr(t, "src") { sm.audio_sources.push(url_resolve(&s)); } } for c in html.split("<img").skip(1) { let t = c.split('>').next().unwrap_or(""); if let Some(s) = Self::attr(t, "src") { sm.image_urls.push(url_resolve(&s)); sm.has_images = true; } } for c in html.split("<iframe").skip(1) { if let Some(s) = Self::attr(c.split('>').next().unwrap_or(""), "src") { if s.contains("youtube") || s.contains("youtu.be") || s.contains("bilibili") { sm.has_video = true; } } } sm }
fn url_resolve(h: &str) -> String { if h.starts_with("http://") || h.starts_with("https://") { h.to_string() } else if h.starts_with("//") { format!("https:{h}") } else { h.to_string() } }
fn extract_text(html: &str) -> String { let mut t = String::new(); let mut it = false; let mut sd = 0u32; let mut std = 0u32; let mut ch = html.chars().peekable(); while let Some(c) = ch.next() { match c { '<' => { it = true; let r: String = ch.clone().collect(); let rl = r.to_lowercase(); if rl.starts_with("script") || rl.starts_with("script ") { sd += 1; } if rl.starts_with("style") || rl.starts_with("style ") { std += 1; } if sd > 0 && rl.contains("/script") { sd = sd.saturating_sub(1); } if std > 0 && rl.contains("/style") { std = std.saturating_sub(1); } } '>' if it => it = false, _ if !it && sd == 0 && std == 0 => { if c.is_alphanumeric() || c.is_whitespace() { t.push(c); } else if c == '\n' || c == '\r' { t.push(' '); } } _ => {} } } t.split_whitespace().collect::<Vec<_>>().join(" ") }
fn video_id(url: &str) -> String { if let Some(s) = url.find("v=") { let id = url[s+2..].split('&').next().unwrap_or("").to_string(); if id.len() == 11 { return id; } } if url.contains("youtu.be/") { if let Some(id) = url.split("youtu.be/").nth(1) { let c = id.split('?').next().unwrap_or(id).split('/').next().unwrap_or(""); if c.len() == 11 { return c.to_string(); } } } if url.contains("/video/") { if let Some(id) = url.split("/video/").nth(1) { return id.split('?').next().unwrap_or(id).split('/').next().unwrap_or("").to_string(); } } url.rsplit('/').next().unwrap_or(url).split('?').next().unwrap_or("").to_string() }
}
